#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <math.h>
#include <float.h>

template <typename scalar_t>
__global__ __launch_bounds__(256)
void attention_kernel(
    const scalar_t* __restrict__ Q,
    const scalar_t* __restrict__ K,
    const scalar_t* __restrict__ V,
    scalar_t* __restrict__ output,
    int q_len,
    int kv_len,
    int head_dim,
    int num_kv_heads,
    float scale,
    bool causal
) {
    int b = blockIdx.x;
    int h = blockIdx.y;
    int q_pos = blockIdx.z;

    int num_heads = gridDim.y;
    int q_BH_stride = q_len * head_dim;
    int kv_BH_stride = kv_len * head_dim;
    int base_q = (b * num_heads + h) * q_BH_stride + q_pos * head_dim;
    int kv_h = h / (num_heads / num_kv_heads);
    int base_kv = (b * num_kv_heads + kv_h) * kv_BH_stride;
    int full_q_pos = kv_len - q_len + q_pos;

    extern __shared__ float smem[];
    float* scores = smem;
    float* s_q = smem + kv_len;
    float* warp_reduce = smem + kv_len + head_dim;

    int tid = threadIdx.x;
    int bdim = blockDim.x;

    const int VEC_ELEMS = 16 / (int)sizeof(scalar_t);
    const int num_q_vecs = head_dim / VEC_ELEMS;

    for (int d4 = tid; d4 < num_q_vecs; d4 += bdim) {
        float4 qv = __ldg(reinterpret_cast<const float4*>(Q + base_q) + d4);
        const scalar_t* qe = reinterpret_cast<const scalar_t*>(&qv);
        #pragma unroll
        for (int j = 0; j < VEC_ELEMS; j++) {
            s_q[d4 * VEC_ELEMS + j] = static_cast<float>(qe[j]);
        }
    }
    for (int d = num_q_vecs * VEC_ELEMS + tid; d < head_dim; d += bdim) {
        s_q[d] = static_cast<float>(__ldg(&Q[base_q + d]));
    }
    __syncthreads();

    float local_max = -FLT_MAX;
    for (int j = tid; j < kv_len; j += bdim) {
        if (causal && j > full_q_pos) {
            scores[j] = -FLT_MAX;
        } else {
            float dot = 0.0f;
            int base_k = base_kv + j * head_dim;
            for (int d4 = 0; d4 < num_q_vecs; d4++) {
                float4 kv = __ldg(reinterpret_cast<const float4*>(K + base_k) + d4);
                const scalar_t* ke = reinterpret_cast<const scalar_t*>(&kv);
                #pragma unroll
                for (int j2 = 0; j2 < VEC_ELEMS; j2++) {
                    dot += s_q[d4 * VEC_ELEMS + j2] * static_cast<float>(ke[j2]);
                }
            }
            for (int d = num_q_vecs * VEC_ELEMS; d < head_dim; d++) {
                dot += s_q[d] * static_cast<float>(__ldg(&K[base_k + d]));
            }
            scores[j] = dot * scale;
        }
        local_max = fmaxf(local_max, scores[j]);
    }

    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        local_max = fmaxf(local_max, __shfl_down_sync(0xffffffff, local_max, offset));

    int lane = tid & 31;
    int warp_id = tid >> 5;
    int num_warps = (bdim + 31) >> 5;

    if (lane == 0) warp_reduce[warp_id] = local_max;
    __syncthreads();

    float global_max = -FLT_MAX;
    for (int i = lane; i < num_warps; i += 32)
        global_max = fmaxf(global_max, warp_reduce[i]);
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        global_max = fmaxf(global_max, __shfl_down_sync(0xffffffff, global_max, offset));
    global_max = __shfl_sync(0xffffffff, global_max, 0);

    float local_sum = 0.0f;
    for (int j = tid; j < kv_len; j += bdim) {
        float e = expf(scores[j] - global_max);
        scores[j] = e;
        local_sum += e;
    }

    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);

    if (lane == 0) warp_reduce[warp_id] = local_sum;
    __syncthreads();

    float global_sum = 0.0f;
    for (int i = lane; i < num_warps; i += 32)
        global_sum += warp_reduce[i];
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        global_sum += __shfl_down_sync(0xffffffff, global_sum, offset);
    global_sum = __shfl_sync(0xffffffff, global_sum, 0);

    float inv_sum = 1.0f / global_sum;

    for (int d = tid; d < head_dim; d += bdim) {
        float acc = 0.0f;
        for (int j = 0; j < kv_len; j++) {
            int base_v = base_kv + j * head_dim;
            acc += scores[j] * static_cast<float>(__ldg(&V[base_v + d]));
        }
        output[base_q + d] = static_cast<scalar_t>(acc * inv_sum);
    }
}

torch::Tensor agent_attention(
    torch::Tensor Q,
    torch::Tensor K,
    torch::Tensor V,
    bool causal
) {
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "attention: Q, K, V must be [batch, heads, len, head_dim]");
